async fn wait_native_job(state:&video_kadr_backend::state::AppState,id:&str)->video_kadr_backend::model::Job{
 let deadline=tokio::time::Instant::now()+std::time::Duration::from_secs(60);
 loop{let job=state.get_job(id).await.unwrap().unwrap();if job.status.is_terminal(){return job}assert!(tokio::time::Instant::now()<deadline,"job did not terminate: {job:?}");tokio::time::sleep(std::time::Duration::from_millis(100)).await;}
}
